// src/circuits/vkey.ts
function toField(buf) {
  return "0x" + Buffer.from(buf).toString("hex").padStart(64, "0");
}
function ultraVkToFields(bytes) {
  const fields = [];
  for (let offset = 0; offset < bytes.length; offset += 32) {
    fields.push(toField(bytes.slice(offset, offset + 32)));
  }
  return fields;
}
function getNumberOfPublicInputsFromVkey(vkey) {
  const num_public_inputs = toField(vkey.slice(32, 64));
  return parseInt(num_public_inputs, 16) - 16;
}

export {
  ultraVkToFields,
  getNumberOfPublicInputsFromVkey
};
